"""Local text embedding behind a swappable Embedder seam.

Available engine:
- ``FastEmbedEmbedder`` (ONNX, no torch) — lower memory footprint, fast inference.
"""

from abc import ABC, abstractmethod
from functools import cached_property
from typing import List, Optional

import numpy as np

from rasa.builder.document_retrieval.local.config import EmbedConfig


class Embedder(ABC):
    """Embeds text for indexing and querying."""

    @abstractmethod
    def encode(self, texts: List[str]) -> np.ndarray:
        """Embed a batch of texts. Returns a 2D float32 array (n, dim)."""

    @property
    @abstractmethod
    def dim(self) -> int:
        """Embedding dimensionality, used to define the vector column."""

    def encode_one(self, text: str) -> np.ndarray:
        """Embed a single text. Returns a 1D float32 array (dim,)."""
        return self.encode([text])[0]


class FastEmbedEmbedder(Embedder):
    """Embedder backed by fastembed (ONNX runtime, no torch)."""

    def __init__(
        self, model_name: str, batch_size: int, cache_dir: Optional[str] = None
    ) -> None:
        # Lazy heavy import: onnxruntime loads only when this engine is built.
        from fastembed import TextEmbedding

        self._model_name = model_name
        self._model = TextEmbedding(model_name=model_name, cache_dir=cache_dir)
        self._batch_size = batch_size

    def encode(self, texts: List[str]) -> np.ndarray:
        # fastembed.embed returns a generator of 1D np arrays (normalized for
        # bge models). parallel=None uses onnxruntime's internal threading
        # (fast); a small batch_size bounds peak memory.
        vectors = self._model.embed(texts, parallel=None, batch_size=self._batch_size)
        return np.array(list(vectors), dtype=np.float32)

    @cached_property
    def dim(self) -> int:
        return int(self.encode_one("dimension probe").shape[0])


def build_embedder(config: EmbedConfig) -> Embedder:
    """Construct the configured embedding engine, loading from its cache dir."""
    if config.embed_engine == "fastembed":
        return FastEmbedEmbedder(
            config.embed_model, config.index_batch_size, config.embed_cache_dir
        )
    raise ValueError(f"Unknown embed_engine: {config.embed_engine}")
